/bin/bash -lc "python3 - <<'PY'
import re
from pathlib import Path
log = Path('/home/drx/.cache/mipstarre-dev/scratch/prover-245-register-transport/axioms.log').read_text()
closures = re.findall(r\"'(["'^'"']+)' depends on axioms: \\[(["'^]]*)'"\\]\", log, re.S)
allowed = {'propext', 'Classical.choice', 'Quot.sound'}
for declaration, axiom_list in closures:
    axioms = {axiom.strip() for axiom in axiom_list.split(',')}
    if not axioms <= allowed:
        raise SystemExit(f'unexpected closure: {declaration}: {axioms}')
print(f'Recorded kernel log: {len(closures)} declarations, all standard-axiom closures.')
